"""Generate matching Czech/English custom-server guides for the development feature."""
from pathlib import Path
from build_memory_report import t
root=Path(__file__).resolve().parents[1]/'website'
body=t('Vlastní AI server pro titulky','Your own AI server for subtitles','h1')+t('Vývojová možnost. Veřejný balíček preview.18 tuto novou integraci ještě neobsahuje.','Development feature. The public preview.18 package does not yet include this new integration.','p','lead')
sections=[
('K čemu to slouží','What this is for','OCR běží na počítači s FrameLabem. Rozpoznaný text se posílá na adresu, kterou zadáš; vybraný model jej překládá na svém serveru. Může to být jiný počítač v domácí síti nebo tvůj vlastní lokální server. Obraz ani zvuk se neposílají. Lokální modely i OpenAI zůstávají samostatnými možnostmi.','OCR runs on the FrameLab PC. Recognized text goes to the address you configure; the selected model translates it on that server. This can be another LAN computer or your own local server. No image or audio is sent. Local models and OpenAI remain separate options.'),
('1. Připrav server','1. Prepare the server','Na serveru musí být načtený model a běžet kompatibilní API: OpenAI-compatible Chat Completions (například llama.cpp / LM Studio) nebo Ollama. Adresa musí být z počítače s FrameLabem dosažitelná. Instalaci ani konfiguraci serveru FrameLab nemění. localhost vždy znamená tento počítač.','Load a model on the server and run a compatible API: OpenAI-compatible Chat Completions (for example llama.cpp / LM Studio) or Ollama. Its address must be reachable from the FrameLab PC. FrameLab does not install or reconfigure the server. localhost always means this computer.'),
('2. Připoj FrameLab','2. Connect FrameLab','Otevři Titulky → Způsob překladu → Custom AI server / LAN. Vyber API serveru. Pro OpenAI-compatible zadej například http://192.168.1.100:8080/v1, pro Ollama http://192.168.1.100:11434. Zadává se základní adresa, nikoli celá cesta /chat/completions. Adresa nesmí obsahovat heslo, query parametry ani fragment.','Open Subtitles → Translation provider → Custom AI server / LAN. Select the server protocol. For OpenAI-compatible, for example enter http://192.168.1.100:8080/v1; for Ollama, http://192.168.1.100:11434. Use the base address, not the full /chat/completions path. Do not embed credentials, query parameters or fragments.'),
('3. Vyber model a případný klíč','3. Choose the model and optional key','Stiskni Připojit / načíst modely a vyber Server model. Pokud server seznam neposkytuje, zadej přesné ID ručně, včetně případné cesty. Klíč je volitelný; u serveru bez ověření ho nech prázdný. Ukládá se ve Správci pověření Windows jen pro danou adresu. OpenAI klíč se na vlastní server automaticky neposílá.','Click Connect / refresh models and select Server model. If the server does not expose a list, enter the exact ID manually, including any path. A key is optional; leave it blank for an unauthenticated server. It is stored in Windows Credential Manager for that address only. Your OpenAI key is never automatically forwarded to a custom server.'),
('4. Nastav jazyk a překlad','4. Configure languages and translation','Vyber jazyk původních titulků, cílový jazyk a oblast OCR. Zapni Překládat titulky. Schopnost překládat do zvoleného jazyka záleží na modelu serveru; seznam jazyků ve FrameLabu není zárukou jeho znalostí. Při změně adresy, modelu či parametrů překlad znovu zapni.','Select source subtitle language, target language and OCR region, then enable subtitle translation. Language quality depends on the server model; FrameLab’s language list does not guarantee that model’s competence. Re-enable translation after changing the endpoint, model or parameters.'),
('5. Volitelné parametry','5. Optional parameters','Teplota se posílá jen po zaškrtnutí příslušné volby. Další JSON parametry musejí být podporované konkrétním serverem a modelem. Následující příklad fungoval na testovaném llama.cpp serveru; nejde o univerzální nastavení všech modelů. Ollama používá objekt options. Omez výstup a prodlevu; pro titulky obvykle nechceš dlouhé uvažování.','Temperature is sent only when enabled. Additional JSON parameters must be supported by your exact server and model. The following example worked on the tested llama.cpp server; it is not a universal configuration. Ollama uses an options object. Bound output and timeout; subtitles usually do not need long reasoning.'),
('6. Paměť rozhovoru','6. Conversation memory','Použít poslední repliky rozhovoru přidá omezenou historii původních titulků. Uchovat důležité repliky je další experimentální volba: stejný model na tvém serveru sám vybírá původní věty pro delší uchování. Výchozí stav je vypnuto. Nejde o identifikaci postav. U překladových specialistů nebo slabších modelů může škodit; CUNI tento výběr nepodporuje. V rozbalovacím přehledu lze vidět kontext posledního překladu.','Use recent dialogue adds bounded source history. Remember important dialogue is a further experimental option: the same model on your server selects original lines to retain longer. It defaults off and does not identify characters. Translation specialists or weaker models can perform worse; CUNI does not support this builder. Expand the context panel to inspect what the last translation actually received.'),
('Když něco nefunguje','Troubleshooting','Chyba sítě: ověř adresu, dostupnost serveru a firewall. HTTP chyba: ověř model, klíč a podporované parametry. Neúplná odpověď nebo thinking místo překladu: vypni uvažování způsobem podporovaným modelem, případně uprav limit. FrameLab nepřebírá nástrojová volání ani reasoning jako titulek a neopakuje automaticky neúspěšné API volání. Při chybě tvorby paměti používá poslední původní repliky; stav je vidět v nastavení.','Network error: check address, server reachability and firewall. HTTP error: check model, key and supported parameters. Incomplete answer or thinking instead of translation: disable reasoning using your model’s supported configuration or adjust the limit. FrameLab does not display tool calls or reasoning as captions and does not automatically retry failed API calls. Memory-generation errors fall back to recent original dialogue, with status visible in settings.')]
for i,(cs,en,cz,eng) in enumerate(sections):
 body+='<section class="section">'+t(cs,en,'h2')+t(cz,eng,'p')
 if i==5:body+='<pre><code>{"chat_template_kwargs":{"enable_thinking":false},"reasoning_budget":0}</code></pre>'
 body+='</section>'
body+='<p><a href="../runs/2026-11-24-context-memory/speed50.html">'+t('Server versus OpenAI: 50 + 50 měření','Server versus OpenAI: 50 + 50 measurements')+'</a> · <a href="../runs/2026-11-24-context-memory/live.html">'+t('Paměť ve skutečném FrameLabu','Memory in the actual FrameLab pipeline')+'</a></p>'
head='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">'+t('FrameLab — vlastní AI server','FrameLab — custom AI server','title')
head+='<style>pre{max-width:100%;overflow:auto;padding:16px;background:#192117}code{font-size:14px}</style>'
for f in ['assets/fonts/fonts.css','explore.css','site-i18n.css','site-navigation.css']:head+=f'<link rel="stylesheet" href="../{f}">'
for f in ['site-i18n.js','site-navigation.js']:head+=f'<script defer src="../{f}"></script>'
for lang,name in [('cs','custom-ai.html'),('en','custom-ai-en.html')]:
 (root/'guide'/name).write_text(f'<!doctype html><html lang="{lang}" data-site-page="guide/{name}"><head>'+head+'</head><body><main>'+body+'</main></body></html>',encoding='utf-8')
print('Custom server guides generated in Czech and English.')
